"""Compile existing stateify fixtures and compare their output on scratch."""
import json
import os
from pathlib import Path
import shutil
import subprocess
import uuid

import check as harness

SOURCE = "b33d195deb0c528d5b2a843fff8a2e32813ff7b9"
CASES = {
    "qualification_generated": (["record.go", "values.go"], "d9a7cf2d466e3dee8f9503f726b6fb3891872ec08396f82d6c4765c2b4ae9e98"),
    "qualification_imports": (["generated.go", "record.go", "values.go"], "edd829e345569c74b7567380153b9d0edd2ab34c928b2f842c07ca4c0ebdad0f"),
}
OUT = {"source": SOURCE, "started": harness.utc(), "invocation": str(uuid.uuid4()), "expected": [], "actions": {}, "verdict": "INCOMPLETE", "errors": []}
ARTIFACT = harness.ROOT / "stateify-comments.json"

def persist():
    ARTIFACT.write_text(json.dumps(OUT, indent=2, sort_keys=True) + "\n")

def qualify():
    harness.check(harness.git("rev-parse", "HEAD").decode().strip() == SOURCE, "wrong product checkout")
    carrier = Path(__file__).resolve().parents[3]
    targets = []
    for name, (srcs, _) in CASES.items():
        package = Path("tools/go_stateify") / name
        shutil.copytree(carrier / package, package)
        # Only the stateify action, not its compiler prerequisites, gets a
        # shell-free executor. The compiled target is the original fixture.
        build = package / "BUILD"
        build.write_text('load("//tools/go_stateify:defs.bzl", "go_stateify")\n' + build.read_text() +
                         '\ngo_stateify(name = "scratch_copy", out = "scratch_copy.go", package = ' + repr(str(package)) +
                         ', srcs = ' + repr(srcs) + ', exec_properties = {"container-image": ' + repr(harness.IMAGE) + '})\n')
        targets += [f"//{package}:{name}", f"//{package}:scratch_copy"]
    # Make both library builds exercise the emitted source. Avoid making the
    # separate scratch-only output part of the original library's source set.
    OUT["expected"] = targets
    persist()
    exec_log = harness.ROOT / "stateify.exec"
    bep = harness.ROOT / "stateify.bep"
    command = ["bazel", "--bazelrc=" + os.environ["QA_RC"], "build", "--config=x86_64", "--jobs=48", "--keep_going",
               "--extra_execution_platforms=//tools/bazeldefs:linux_amd64",
               "--spawn_strategy=local", "--strategy=GoStateify=remote",
               "--remote_default_exec_properties=Arch=amd64", "--remote_default_exec_properties=OSFamily=linux",
               "--remote_default_exec_properties=workload-isolation-type=oci",
               "--remote_default_exec_properties=container-image=" + harness.GNU_IMAGE,
               "--modify_execution_info=^GoStateify$=+no-remote-cache", "--invocation_id=" + OUT["invocation"],
               "--execution_log_json_file=" + str(exec_log), "--build_event_json_file=" + str(bep), *targets]
    result = subprocess.run(command, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    OUT["exit"] = result.returncode
    OUT["log_sha256"] = harness.digest(result.stdout.encode())
    OUT["diagnostics"] = [line[:500] for line in result.stdout.splitlines() if line.startswith(("ERROR:", "FAILED:")) and not any(block in line.lower() for block in ("key=", "header", "credential", "token", "command line"))][-15:]
    for event in harness.rows(bep):
        completed = event.get("id", {}).get("targetCompleted", {}).get("label")
        if completed in targets:
            OUT.setdefault("completed", {})[completed] = event.get("completed", {}).get("success", False)
    for spawn in harness.rows(exec_log):
        if spawn.get("mnemonic") != "GoStateify" or "/qualification_" not in spawn.get("targetLabel", ""):
            continue
        label = spawn["targetLabel"]
        name, target = label.rsplit("/", 1)[1].split(":")
        if name not in CASES:
            continue
        image = {v["name"]: v["value"] for v in spawn["platform"]["properties"]}.get("container-image")
        output, = spawn["actualOutputs"]
        row = OUT["actions"][label] = {"image": image, "cached": spawn.get("cacheHit", False), "runner": spawn.get("runner"), "exit": spawn.get("exitCode", 0), "digest": output["digest"]["hash"], "source_directory": [arg for arg in spawn["commandArgs"] if arg.startswith("-srcdir=")]}
        harness.check(row["exit"] == 0 and row["runner"] == "remote" and not row["cached"], "unqualified action: " + label)
        harness.check(image == (harness.IMAGE if target == "scratch_copy" else harness.GNU_IMAGE), "wrong image for " + label)
        harness.check(row["digest"] == CASES[name][1], "generated bytes changed for " + label)
        harness.check(bool(row["source_directory"]) == (name == "qualification_imports"), "wrong source directory for " + label)
    harness.check(result.returncode == 0, "Bazel build returned " + str(result.returncode))
    harness.check(OUT.get("completed") == dict.fromkeys(targets, True), "expected all four targets")
    harness.check(len(OUT["actions"]) == 4, "expected stock-image and scratch-image actions for each fixture")
    OUT["verdict"] = "PASS"

try:
    qualify()
except Exception as exc:
    OUT["errors"].append(str(exc))
    OUT["verdict"] = "FAIL"
finally:
    OUT["finished"] = harness.utc()
    persist()
print(json.dumps(OUT, sort_keys=True))
raise SystemExit(OUT["verdict"] != "PASS")
